\set ON_ERROR_STOP on
begin;
create function pg_temp.b_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Bundle: %',label; end if; end $$;
create function pg_temp.b_fail(q text,expected text) returns void language plpgsql as $$ begin begin execute q; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise; end; raise exception 'Expected %',expected; end $$;
\i /tmp/bundle-native-input.sql
insert into public.users(id,email,verified_at) values ('bb000000-0000-4000-8000-000000000001','agency@example.test',now()),('bb000000-0000-4000-8000-000000000002','owner@example.test',now()),('bb000000-0000-4000-8000-000000000003','reviewer@example.test',now());
