insert into public.workspace_memberships(workspace_id,user_id,role,created_by) values ('bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000001','owner','bb000000-0000-4000-8000-000000000001'),('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','owner','bb000000-0000-4000-8000-000000000002');
