select public.append_website_document('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100','bb000000-0000-4000-8000-000000000002','owner@example.test',0,repeat('a',64),value->'document') from bundle_native_input;
create temp table b_source as select (public.create_system_version_source('bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000001','agency@example.test','{"name":"Complete intake","kind":"other"}','bb000000-0000-4000-8000-000000000020',repeat('b',64))->'system'->>'id')::uuid id;
select public.publish_system_version_source_revision('bb000000-0000-4000-8000-000000000001','agency@example.test',jsonb_build_object('source',jsonb_build_object('businessId','bb000000-0000-4000-8000-000000000010','systemId',(select id from b_source),'revisionId','bb000000-0000-4000-8000-000000000021','number',1),'definition',value->'definition','declaration',public.system_package_behavior(value->'definition','{}'),'summary','App, native inquiry and FAQ section','requires','{"bindingKinds":[]}'::jsonb,'publishedBy','bb000000-0000-4000-8000-000000000001','publishedAt',now())) from bundle_native_input;
select public.record_system_bundle_qualification('bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000001','agency@example.test','bb000000-0000-4000-8000-000000000021',value->'artifacts') from bundle_native_input;
select pg_temp.b_assert((select count(*)=1 from public.system_bundle_native_rehearsals),'actual native rehearsal artifacts stored durably');
insert into public.system_revision_reviewers(user_id,policy_version) values('bb000000-0000-4000-8000-000000000003','fictional-local-review');
select public.review_system_revision_qualification('bb000000-0000-4000-8000-000000000003','reviewer@example.test','bb000000-0000-4000-8000-000000000021',true,'Reviewed exact native multi-System source');
select public.set_system_package_listing('bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000001','agency@example.test',(select id from b_source),'listed');
select pg_temp.b_fail($q$select public.system_package_behavior('{"kind":"inquiry_pattern","name":"Intake","title":"Intake","intro":"","fields":[{"id":"name","label":"Name","required":true}],"routingWithinMinutes":60}', '{}')$q$,'system_package_input_invalid');
select pg_temp.b_fail($q$select public.system_package_behavior('{"kind":"website_section","title":"FAQ","items":[{"question":42,"answer":43}]}', '{}')$q$,'system_package_input_invalid');
select pg_temp.b_assert((select public.system_package_behavior(value->'definition','{}')->'outsideEffects' @> '["email","publish"]'::jsonb from bundle_native_input),'aggregate declaration includes actual inquiry and website effects');
select pg_temp.b_fail($q$select public.system_package_rehearsal('{"kind":"website_section","title":"FAQ","items":[{"question":"Q","answer":"A"}]}')$q$,'system_bundle_native_rehearsal_required');
create function pg_temp.b_targets() returns jsonb language sql as $$ select '{"inquiryTenantId":"bundle-target","websiteWorkId":"bb000000-0000-4000-8000-000000000100","websitePagePath":"/services"}'::jsonb $$;
create function pg_temp.b_install(actor uuid,email text,command uuid,expected bigint,partkey text,statekey text,workrevision integer default 1) returns jsonb language sql as $$ select public.install_system_bundle('bb000000-0000-4000-8000-000000000011',actor,email,'bb000000-0000-4000-8000-000000000021',(select id from b_source),'bb000000-0000-4000-8000-000000000010',1,command,'Complete intake',pg_temp.b_targets(),expected,workrevision,1,value->partkey,value->statekey) from bundle_native_input $$;
select pg_temp.b_fail($q$select pg_temp.b_install('bb000000-0000-4000-8000-000000000002','owner@example.test','bb000000-0000-4000-8000-000000000030',null,'ownerParts','ownerState',999)$q$,'system_version_stale');
select pg_temp.b_assert((select count(*)=0 from public.system_bundle_installations),'stale target leaves no partial installation');
select pg_temp.b_fail($q$select public.install_system_bundle('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','owner@example.test','bb000000-0000-4000-8000-000000000021',(select id from b_source),'bb000000-0000-4000-8000-000000000010',1,'bb000000-0000-4000-8000-000000000040','Complete intake',pg_temp.b_targets(),null,1,1,jsonb_set(value->'ownerParts','{2,document,nodes}', '{}'::jsonb),value->'ownerState') from bundle_native_input$q$,'system_bundle_website_invalid');
select pg_temp.b_assert((select count(*)=0 from public.system_bundle_installations),'later website failure rolls back earlier app inquiry and lineage drafts');

create temp table b_owner as select pg_temp.b_install('bb000000-0000-4000-8000-000000000002','owner@example.test','bb000000-0000-4000-8000-000000000030',null,'ownerParts','ownerState') receipt;
select pg_temp.b_assert((select jsonb_array_length(receipt->'components')=3 from b_owner),'one exact source installs three actual native drafts');
select pg_temp.b_assert((select count(*)=3 from public.system_versions where business_workspace_id='bb000000-0000-4000-8000-000000000011' and current_release is null),'component Versions independent and none live');
