select pg_temp.b_assert((select payload->'candidate'->'document'=value->'document' from public.saved_product_work cross join bundle_native_input where id='bb000000-0000-4000-8000-000000000100'),'original target website remains intact');
select pg_temp.b_assert(pg_temp.b_install('bb000000-0000-4000-8000-000000000002','owner@example.test','bb000000-0000-4000-8000-000000000030',null,'ownerParts','ownerState')=(select receipt from b_owner),'uncertain reply reopens exact same bundle');
select pg_temp.b_fail($q$select pg_temp.b_install('bb000000-0000-4000-8000-000000000001','agency@example.test','bb000000-0000-4000-8000-000000000031',1,'agencyParts','agencyState')$q$,'business_record_access_denied');
insert into public.workspace_delegations(customer_workspace_id,customer_work_id,agency_workspace_id,granted_by,accepted_by) values('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100','bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000002','bb000000-0000-4000-8000-000000000001');
select public.grant_system_package_install('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','owner@example.test','bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000021','bb000000-0000-4000-8000-000000000031',now()+interval '1 day');
select pg_temp.b_fail($q$select pg_temp.b_install('bb000000-0000-4000-8000-000000000001','agency@example.test','bb000000-0000-4000-8000-000000000031',1,'agencyParts','agencyState')$q$,'business_record_access_denied');
select public.grant_system_bundle_targets('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','owner@example.test',id,pg_temp.b_targets()) from public.system_package_install_grants where command_id='bb000000-0000-4000-8000-000000000031';
