select pg_temp.b_fail($q$select public.read_system_bundle_targets('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','agency@example.test','bb000000-0000-4000-8000-000000000021','bb000000-0000-4000-8000-000000000031',pg_temp.b_targets())$q$,'business_record_access_denied');
select pg_temp.b_assert(public.read_system_bundle_install_receipt('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','agency@example.test','bb000000-0000-4000-8000-000000000021','bb000000-0000-4000-8000-000000000031','Complete intake',pg_temp.b_targets())=(select receipt from b_agency),'completed delegate retry reads receipt without original native data');
select pg_temp.b_assert(not exists(select 1 from public.workspace_memberships where workspace_id='bb000000-0000-4000-8000-000000000011' and user_id='bb000000-0000-4000-8000-000000000001'),'agency never becomes client admin');
select pg_temp.b_assert(cardinality(public.system_bundle_read_work_ids('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','agency@example.test'))=3,'exact completed grant grants read of installed drafts');
select pg_temp.b_fail($q$select public.website_document_assert_actor('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000104','bb000000-0000-4000-8000-000000000001','agency@example.test',false,true)$q$,'workspace_access_denied');
select pg_temp.b_assert(not public.system_in_scope('bb000000-0000-4000-8000-000000000011','saved_work','bb000000-0000-4000-8000-000000000104',(public.system_actor_scope('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','agency@example.test',true)).work_ids),'completed receipt removes transient System writer');
select pg_temp.b_assert((select count(*)=3 from jsonb_array_elements(public.read_version_actor('bb000000-0000-4000-8000-000000000001','agency@example.test')->'delegatedSystems') d where d->'canWrite'='false'::jsonb),'delegated component pages expose only read authority');
