select public.revoke_system_package_install('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','owner@example.test',id) from public.system_package_install_grants where command_id='bb000000-0000-4000-8000-000000000031';
select pg_temp.b_assert(cardinality(public.system_bundle_read_work_ids('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','agency@example.test'))=0,'revocation closes installed draft read access');
select pg_temp.b_assert(not has_function_privilege('authenticated','public.install_system_bundle(uuid,uuid,text,uuid,uuid,uuid,integer,uuid,text,jsonb,bigint,integer,integer,jsonb,jsonb)','EXECUTE'),'RPC native bundle install not directly callable');
